"""Deterministic build order for a dependency graph. See task.md."""

from __future__ import annotations

import heapq
from collections import deque


class CycleError(ValueError):
    """Raised when the graph contains a cycle.

    `.cycle` names the members of the reported cycle, in depends-on order,
    without repeating the first member at the end.
    """

    def __init__(self, cycle: list[str]) -> None:
        super().__init__("dependency cycle: " + " -> ".join(cycle))
        self.cycle = list(cycle)


def resolve(graph: dict[str, list[str]]) -> list[str]:
    """Return the build order of `graph`, dependencies first."""
    nodes = set(graph)
    for targets in graph.values():
        nodes.update(targets)

    deps = {node: set(graph.get(node, ())) for node in nodes}
    dependents: dict[str, list[str]] = {node: [] for node in nodes}
    remaining = {}
    for node in nodes:
        remaining[node] = len(deps[node])
        for dep in deps[node]:
            dependents[dep].append(node)

    ready = [node for node in nodes if remaining[node] == 0]
    heapq.heapify(ready)
    order: list[str] = []
    while ready:
        node = heapq.heappop(ready)
        order.append(node)
        for dependent in dependents[node]:
            remaining[dependent] -= 1
            if remaining[dependent] == 0:
                heapq.heappush(ready, dependent)

    if len(order) == len(nodes):
        return order
    pending = nodes.difference(order)
    raise CycleError(_find_cycle(deps, pending))


def _find_cycle(deps: dict[str, set[str]], pending: set[str]) -> list[str]:
    adj = {node: sorted(deps[node] & pending) for node in pending}
    length = min(
        n for n in (_shortest_return(adj, s) for s in pending) if n is not None
    )
    for start in sorted(pending):
        cycle = _cycle_from(adj, start, length)
        if cycle is not None:
            return cycle
    raise AssertionError("cycle expected but none found")


def _shortest_return(adj: dict[str, list[str]], start: str) -> int | None:
    dist = {start: 0}
    queue = deque([start])
    while queue:
        node = queue.popleft()
        for nxt in adj[node]:
            if nxt == start:
                return dist[node] + 1
            if nxt not in dist:
                dist[nxt] = dist[node] + 1
                queue.append(nxt)
    return None


def _cycle_from(adj: dict[str, list[str]], start: str, length: int) -> list[str] | None:
    members = {node for node in adj if node >= start}
    rev: dict[str, list[str]] = {node: [] for node in members}
    for node in members:
        for nxt in adj[node]:
            if nxt in members:
                rev[nxt].append(node)

    dist = {start: 0}
    queue = deque([start])
    while queue:
        node = queue.popleft()
        for prev in rev[node]:
            if prev not in dist:
                dist[prev] = dist[node] + 1
                queue.append(prev)

    path = [start]
    on_path = {start}

    def extend(node: str) -> bool:
        edges = len(path) - 1
        for nxt in adj[node]:
            if nxt == start:
                if edges + 1 == length:
                    return True
                continue
            if nxt in dist and nxt not in on_path and edges + 1 + dist[nxt] <= length:
                path.append(nxt)
                on_path.add(nxt)
                if extend(nxt):
                    return True
                path.pop()
                on_path.discard(nxt)
        return False

    return list(path) if extend(start) else None
